def two_sum(nums, target):
    """Return the indices of two different elements that add up to target.

    If no such pair exists, both elements may be taken as the same value:
    a single element whose value is exactly half of the target is used for
    both positions (the indices returned are distinct).
    """
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [i, j]
    if target % 2 == 0:
        half = target // 2
        first = None
        for i in range(len(nums)):
            if nums[i] == half:
                if first is None:
                    first = i
                else:
                    return [first, i]
        if first is not None:
            return [first, first]
    return None

